'use strict';

const express = require('express');
const Database = require('better-sqlite3');

function createApp(dbPath = ':memory:') {
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');

  db.exec(`
    CREATE TABLE IF NOT EXISTS articles (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      body TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
      updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
      deleted_at TEXT
    );
  `);

  const app = express();
  app.use(express.json());

  const stmts = {
    insert: db.prepare(
      'INSERT INTO articles (title, body) VALUES (?, ?)'
    ),
    listActive: db.prepare(
      'SELECT * FROM articles WHERE deleted_at IS NULL ORDER BY id'
    ),
    getByIdActive: db.prepare(
      'SELECT * FROM articles WHERE id = ? AND deleted_at IS NULL'
    ),
    getByIdIncludingDeleted: db.prepare(
      'SELECT * FROM articles WHERE id = ?'
    ),
    softDelete: db.prepare(
      "UPDATE articles SET deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = ? AND deleted_at IS NULL"
    ),
    restore: db.prepare(
      'UPDATE articles SET deleted_at = NULL, updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\',\'now\') WHERE id = ? AND deleted_at IS NOT NULL'
    ),
  };

  // Create an article.
  app.post('/articles', (req, res) => {
    const { title, body = '' } = req.body || {};
    if (!title || typeof title !== 'string') {
      return res.status(400).json({ error: 'title is required' });
    }
    const info = stmts.insert.run(title, String(body));
    const article = stmts.getByIdActive.get(info.lastInsertRowid);
    res.status(201).json(article);
  });

  // List only non-deleted articles.
  app.get('/articles', (_req, res) => {
    res.json(stmts.listActive.all());
  });

  // Fetch a single non-deleted article; deleted ones look like they don't exist.
  app.get('/articles/:id', (req, res) => {
    const article = stmts.getByIdActive.get(Number(req.params.id));
    if (!article) return res.status(404).json({ error: 'article not found' });
    res.json(article);
  });

  // Soft delete: stamp deleted_at, keep the row.
  app.delete('/articles/:id', (req, res) => {
    const id = Number(req.params.id);
    if (!stmts.getByIdActive.get(id)) {
      return res.status(404).json({ error: 'article not found' });
    }
    stmts.softDelete.run(id);
    return res.status(204).end();
  });

  // Restore a soft-deleted article.
  app.post('/articles/:id/restore', (req, res) => {
    const id = Number(req.params.id);
    const restored = stmts.restore.run(id);
    if (restored.changes === 0) {
      return res.status(404).json({ error: 'article not found or not deleted' });
    }
    res.json(stmts.getByIdActive.get(id));
  });

  // Test-only helper to close the DB handle cleanly.
  app.closeDb = () => db.close();

  return app;
}

module.exports = { createApp };

