'use strict';

const request = require('supertest');
const Database = require('better-sqlite3');
const os = require('os');
const path = require('path');
const fs = require('fs');
const { createApp } = require('../src/app');

// File-backed DB so tests can verify rows directly, independent of the HTTP layer.
const dbPath = path.join(os.tmpdir(), `articles-test-${process.pid}-${Date.now()}.db`);

describe('articles API — soft delete lifecycle', () => {
  let app;

  beforeAll(() => {
    app = createApp(dbPath);
  });

  afterAll(() => {
    app.closeDb();
    fs.rmSync(dbPath, { force: true });
    fs.rmSync(`${dbPath}-wal`, { force: true });
    fs.rmSync(`${dbPath}-shm`, { force: true });
  });

  test('full lifecycle: create -> delete (vanishes) -> restore -> back', async () => {
    // Seed two articles so list counts are meaningful.
    const a = await request(app).post('/articles').send({ title: 'First', body: 'alpha' });
    expect(a.status).toBe(201);
    const b = await request(app).post('/articles').send({ title: 'Second', body: 'beta' });
    expect(b.status).toBe(201);
    const targetId = a.body.id;
    const otherId = b.body.id;

    // Baseline: both visible.
    let list = await request(app).get('/articles');
    expect(list.status).toBe(200);
    expect(list.body).toHaveLength(2);
    await expect(
      request(app).get(`/articles/${targetId}`)
    ).resolves.toMatchObject({ status: 200, body: { id: targetId, title: 'First' } });

    // DELETE: soft-deletes the target.
    const del = await request(app).delete(`/articles/${targetId}`);
    expect(del.status).toBe(204);

    // List drops from 2 to 1; only the other article remains.
    list = await request(app).get('/articles');
    expect(list.status).toBe(200);
    expect(list.body).toHaveLength(1);
    expect(list.body.map((x) => x.id)).toEqual([otherId]);

    // GET by id now 404s for the deleted article...
    const gone = await request(app).get(`/articles/${targetId}`);
    expect(gone.status).toBe(404);

    // ...but the row is still physically present with deleted_at set (direct DB check).
    const rawDb = new Database(dbPath);
    try {
      const row = rawDb.prepare('SELECT * FROM articles WHERE id = ?').get(targetId);
      expect(row).toBeDefined();
      expect(row.title).toBe('First');
      expect(row.deleted_at).not.toBeNull();
      // deleted_at parses as a real timestamp.
      expect(Number.isNaN(Date.parse(row.deleted_at))).toBe(false);

      // Exactly one soft-deleted row in total.
      const deletedCount = rawDb
        .prepare('SELECT COUNT(*) AS n FROM articles WHERE deleted_at IS NOT NULL')
        .get().n;
      expect(deletedCount).toBe(1);
    } finally {
      rawDb.close();
    }

    // Second DELETE of the already-deleted article -> 404.
    const secondDelete = await request(app).delete(`/articles/${targetId}`);
    expect(secondDelete.status).toBe(404);

    // RESTORE brings it back.
    const restored = await request(app).post(`/articles/${targetId}/restore`);
    expect(restored.status).toBe(200);
    expect(restored.body).toMatchObject({ id: targetId, title: 'First', deleted_at: null });

    // List count recovers to 2 and includes the restored article.
    list = await request(app).get('/articles');
    expect(list.status).toBe(200);
    expect(list.body).toHaveLength(2);
    expect(list.body.map((x) => x.id).sort()).toEqual([targetId, otherId].sort());
    await expect(
      request(app).get(`/articles/${targetId}`)
    ).resolves.toMatchObject({ status: 200, body: { id: targetId, deleted_at: null } });
  });

  test('restore of a non-deleted or nonexistent article returns 404', async () => {
    await expect(
      request(app).post('/articles/999999/restore')
    ).resolves.toMatchObject({ status: 404 });
  });

  test('deleting a nonexistent article returns 404', async () => {
    await expect(
      request(app).delete('/articles/999999')
    ).resolves.toMatchObject({ status: 404 });
  });

  test('POST /articles validates title', async () => {
    const res = await request(app).post('/articles').send({});
    expect(res.status).toBe(400);
  });
});

